CREATE SEQUENCE IF NOT EXISTS order_number_seq;
DO $$ BEGIN CREATE TYPE order_status AS ENUM ('DRAFT','PENDING_PAYMENT','CONFIRMED','CANCELLED','COMPLETED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE payment_status AS ENUM ('UNPAID','PROCESSING','PAID','FAILED','PARTIALLY_REFUNDED','REFUNDED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE fulfillment_status AS ENUM ('UNFULFILLED','PICKING','PACKED','SHIPPED','DELIVERED','RETURNED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_number text NOT NULL UNIQUE DEFAULT ('ORD-' || to_char(now(), 'YYYY') || '-' || lpad(nextval('order_number_seq')::text, 6, '0')), customer_id uuid NULL, email text NOT NULL, phone text NULL, currency varchar(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'), subtotal_minor integer NOT NULL CHECK (subtotal_minor >= 0), discount_total_minor integer NOT NULL DEFAULT 0 CHECK (discount_total_minor >= 0), shipping_total_minor integer NOT NULL DEFAULT 0 CHECK (shipping_total_minor >= 0), tax_total_minor integer NOT NULL DEFAULT 0 CHECK (tax_total_minor >= 0), grand_total_minor integer NOT NULL CHECK (grand_total_minor >= 0), order_status order_status NOT NULL DEFAULT 'PENDING_PAYMENT', payment_status payment_status NOT NULL DEFAULT 'UNPAID', fulfillment_status fulfillment_status NOT NULL DEFAULT 'UNFULFILLED', shipping_country_code varchar(2) NULL, shipping_address_json jsonb NULL, billing_address_json jsonb NULL, source text NOT NULL DEFAULT 'ONLINE_CHECKOUT', purchase_request_id uuid NULL REFERENCES purchase_requests(id) ON DELETE SET NULL, requires_review boolean NOT NULL DEFAULT false, review_reason text NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS order_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders(id) ON DELETE RESTRICT, product_id uuid NULL REFERENCES products(id) ON DELETE SET NULL, variant_id uuid NULL REFERENCES product_variants(id) ON DELETE SET NULL, product_name_snapshot text NOT NULL, sku_snapshot text NOT NULL, color_snapshot text NOT NULL, size_snapshot text NOT NULL, unit_price_minor integer NOT NULL CHECK (unit_price_minor >= 0), quantity integer NOT NULL CHECK (quantity > 0), line_total_minor integer NOT NULL CHECK (line_total_minor >= 0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders(id) ON DELETE RESTRICT, provider text NOT NULL, provider_payment_id text NULL, provider_checkout_session_id text NULL, amount_minor integer NOT NULL CHECK (amount_minor >= 0), currency varchar(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'), status payment_status NOT NULL DEFAULT 'UNPAID', failure_code text NULL, failure_message text NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), paid_at timestamptz NULL, UNIQUE(provider, provider_checkout_session_id));
CREATE TABLE IF NOT EXISTS webhook_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider text NOT NULL, provider_event_id text NOT NULL, event_type text NOT NULL, processed_at timestamptz NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider, provider_event_id));
CREATE TABLE IF NOT EXISTS outbox_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_type text NOT NULL, aggregate_type text NOT NULL, aggregate_id uuid NOT NULL, payload_json jsonb NOT NULL, attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0), processed_at timestamptz NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS orders_number_idx ON orders(order_number); CREATE INDEX IF NOT EXISTS orders_email_idx ON orders(email); CREATE INDEX IF NOT EXISTS orders_status_idx ON orders(order_status); CREATE INDEX IF NOT EXISTS orders_created_idx ON orders(created_at); CREATE INDEX IF NOT EXISTS order_items_order_idx ON order_items(order_id); CREATE INDEX IF NOT EXISTS payments_order_idx ON payments(order_id); CREATE INDEX IF NOT EXISTS payments_session_idx ON payments(provider_checkout_session_id); CREATE INDEX IF NOT EXISTS outbox_unprocessed_idx ON outbox_events(processed_at) WHERE processed_at IS NULL;
